1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11		"github.com/entireio/cli/cmd/entire/cli/agent/external"
12		"github.com/entireio/cli/cmd/entire/cli/agent/types"
13		"github.com/entireio/cli/cmd/entire/cli/interactive"
14		"github.com/entireio/cli/cmd/entire/cli/logging"
15		"github.com/entireio/cli/cmd/entire/cli/paths"
16		"github.com/entireio/cli/cmd/entire/cli/settings"
17		"github.com/entireio/cli/cmd/entire/cli/summarize"
18	
19		"github.com/charmbracelet/huh"
20	)
21	
22	var (
23		loadSummarySettings         = LoadEntireSettings
24		loadSummarySettingsFromFile = settings.LoadFromFile
25		saveLocalSummarySettings    = SaveEntireSettingsLocal
26		getSummaryAgent             = agent.Get
27		listRegisteredAgents        = agent.List
28		isSummaryCLIAvailable       = agent.IsSummaryCLIAvailable
29		discoverSummaryProviders    = external.DiscoverAndRegister
30	)
31	
32	type checkpointSummaryProvider struct {
33		Name        types.AgentName
34		DisplayName string
35		Model       string
36		Generator   summarize.Generator
37	}
38	
39	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
40		s, err := loadSummarySettings(ctx)
41		if err != nil {
42			return nil, fmt.Errorf("loading settings: %w", err)
43		}
44	
45		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
46			providerName := types.AgentName(s.SummaryGeneration.Provider)
47			discoverSummaryProviderIfMissing(ctx, providerName)
48			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
49				return nil, err
50			}
51			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
52		}
53	
54		discoverSummaryProviders(ctx)
55		candidates := listEnabledSummaryProviders(ctx)
56	
57		switch len(candidates) {
58		case 0:
59			return nil, errors.New("no summary-capable provider is available; install claude, codex, gemini, cursor, or copilot, install an external entire-agent-* plugin that declares text_generator, or set summary_generation.provider in settings")
60		case 1:
61			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
62		default:
63			if !interactive.CanPromptInteractively() {
64				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
65			}
66	
67			selected, err := promptForSummaryProvider(candidates)
68			if err != nil {
69				return nil, err
70			}
71			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
72			if err != nil {
73				return nil, err
74			}
75			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
76			return provider, nil
77		}
78	}
79	
80	func discoverSummaryProviderIfMissing(ctx context.Context, name types.AgentName) {
81		if _, err := getSummaryAgent(name); err == nil {
82			return
83		}
84		discoverSummaryProviders(ctx)
85	}
86	
87	// autoSelectSummaryProvider builds a provider for an auto-selected candidate
88	// (single-installed or non-interactive-first-of-many) and persists the choice
89	// so subsequent runs don't re-decide. Persistence failure is surfaced as a
90	// warning — not an error — because the selection is still usable in-process.
91	func autoSelectSummaryProvider(ctx context.Context, w io.Writer, name types.AgentName, reason string) (*checkpointSummaryProvider, error) {
92		logging.Info(ctx, reason, "provider", string(name))
93		provider, err := buildCheckpointSummaryProvider(name, "")
94		if err != nil {
95			return nil, err
96		}
97		if saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model); saveErr != nil {
98			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
99				"error", saveErr.Error())
100			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
101		}
102		return provider, nil
103	}
104	
105	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
106		registered := listRegisteredAgents()
107		providers := make([]checkpointSummaryProvider, 0, len(registered))
108		for _, name := range registered {
109			ag, err := getSummaryAgent(name)
110			if err != nil {
111				continue
112			}
113			if _, ok := agent.AsTextGenerator(ag); !ok {
114				continue
115			}
116			// Check CLI binary on PATH for built-ins. External agents are already
117			// proven executable by discovery and are gated by text_generator.
118			if !isSummaryProviderAvailable(name, ag) {
119				continue
120			}
121			providers = append(providers, checkpointSummaryProvider{
122				Name:        name,
123				DisplayName: string(ag.Type()),
124			})
125		}
126		return providers
127	}
128	
129	func isSummaryProviderAvailable(name types.AgentName, ag agent.Agent) bool {
130		if external.IsExternal(ag) {
131			_, ok := agent.AsTextGenerator(ag)
132			return ok
133		}
134		return isSummaryCLIAvailable(name)
135	}
136	
137	func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
138		options := make([]huh.Option[string], 0, len(providers))
139		for _, provider := range providers {
140			options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
141		}
142	
143		var selected string
144		form := NewAccessibleForm(
145			huh.NewGroup(
146				huh.NewSelect[string]().
147					Title("Choose a summary provider").
148					Description("This choice will be saved. Use `entire configure` to change it later.").
149					Options(options...).
150					Value(&selected),
151			),
152		)
153		if err := form.Run(); err != nil {
154			return "", fmt.Errorf("summary provider selection cancelled: %w", err)
155		}
156	
157		return types.AgentName(selected), nil
158	}
159	
160	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
161		ag, err := getSummaryAgent(name)
162		if err != nil {
163			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
164		}
165	
166		textGenerator, ok := agent.AsTextGenerator(ag)
167		if !ok {
168			return nil, fmt.Errorf("agent %s does not support summary generation", name)
169		}
170	
171		effectiveModel := summarize.ResolveModel(name, model)
172	
173		return &checkpointSummaryProvider{
174			Name:        name,
175			DisplayName: string(ag.Type()),
176			Model:       effectiveModel,
177			Generator: &summarize.TextGeneratorAdapter{
178				TextGenerator: textGenerator,
179				Model:         effectiveModel,
180			},
181		}, nil
182	}
183	
184	// ensureSummaryProviderPresent returns an error if the named summary provider's
185	// CLI binary is not on PATH. Checks the binary directly (via exec.LookPath)
186	// rather than DetectPresence, because DetectPresence checks repo-level agent
187	// configuration — a repo using Claude Code for development can still use Codex
188	// or Gemini for summary generation as long as the binary is installed.
189	func ensureSummaryProviderPresent(_ context.Context, name types.AgentName) error {
190		ag, err := getSummaryAgent(name)
191		if err != nil {
192			return fmt.Errorf("unknown summary provider %s: %w", name, err)
