func preserveToolOnPath(name, dstDir string) error {
	src, err := exec.LookPath(name)
	if err != nil {
		if errors.Is(err, exec.ErrNotFound) {
			return nil
		}
		return err
	}

	return copyExecutable(src, filepath.Join(dstDir, filepath.Base(src)))
}

